// ═══════════════════════════════════════════════════════════════════════════════════════════════
// AMBIENTES REALISTAS · presets de iluminación + un mando para aplicarlos (con transición suave).
//
// Cada preset compone TODOS los mandos estéticos que hay: el color del cielo, la niebla atmosférica, la
// luz global (día↔noche), el reflejo del agua (fuerza · curva · opacidad · color), el tinte de dentro
// del agua y la dureza de la sombra del sol. Es el esqueleto del dueño, completado. Se afina en vivo:
// edita los números aquí y vuelve a correr.
//
// Uso desde F12:
//   game.entorno('NOCHE')              → lo pone ya
//   game.entorno('ATARDECER', 4)       → transición de 4 segundos desde lo que haya ahora
//   game.entorno()                     → lista los nombres
// ═══════════════════════════════════════════════════════════════════════════════════════════════

const Entornos = {
  // ── Ciclo horario ──────────────────────────────────────────────────────────────────────────
  AMANECER: {   // aurora: sol rasante, el reflejo dorado entibia el agua más que al cenit
    cielo:   [0.95, 0.45, 0.25],
    //niebla:  { near: 20, far: 120, tinte: 0.04 },   // bruma dorada lejana
    niebla:  { near: 100, far: 300, tinte: 0.06 },   
    luz:     0.85,
    reflejo: { fuerza: 0.85, curva: 2.5, opacidad: 0.85, color: [1.0, 0.55, 0.2] },
    agua:    { sky: [0.16, 0.12, 0.10], tinte: 0.16, far: 90, sigueCielo: false },
    sombra:  0.65
  },
  MEDIODIA: {   // luz cenital: solo Fresnel a rasante (curva 5), de frente el agua transparenta
    cielo:   [0.35, 0.65, 0.95],
    niebla:  false,                                  // cristalino
    luz:     1.0,
    reflejo: { fuerza: 0.50, curva: 5.0, opacidad: 0.90, color: 'cielo' },
    agua:    { sky: [0.10, 0.34, 0.60], tinte: 0.10, far: 100, sigueCielo: false },
    sombra:  0.45
  },
  ATARDECER: {  // golden hour: reflejo especular amplio y dominante, dispersión rojiza
    cielo:   [0.90, 0.35, 0.15],
    //niebla:  { near: 25, far: 130, tinte: 0.05 },    // calima cálida
    niebla:  { near: 25, far: 300, tinte: 0.06 },   
    luz:     0.75,
    reflejo: { fuerza: 0.90, curva: 2.0, opacidad: 0.95, color: [1.0, 0.3, 0.1] },
    agua:    { sky: [0.20, 0.10, 0.06], tinte: 0.18, far: 85, sigueCielo: false },
    sombra:  0.6
  },
  NOCHE: {      // luna: reflejo frío y opaco sobre un cielo casi negro
    cielo:   [0.02, 0.03, 0.08],
    niebla:  { near: 15, far: 70, tinte: 0.08 },     // neblina nocturna
    luz:     0.28,
    reflejo: { fuerza: 0.65, curva: 3.0, opacidad: 0.95, color: [0.15, 0.25, 0.4] },
    agua:    { sky: [0.02, 0.04, 0.10], tinte: 0.28, far: 70, sigueCielo: false },
    sombra:  0.9
  },
  // ── Climas adversos ────────────────────────────────────────────────────────────────────────
  NIEBLA: {     // día nublado: luz difusa, se pierde el espejo direccional, gris uniforme
    cielo:   [0.72, 0.75, 0.78],
    niebla:  { near: 3, far: 20, tinte: 0.16 },      // ESPESA: empieza a 3 bloques
    luz:     0.8,
    reflejo: { fuerza: 0.35, curva: 2.0, opacidad: 0.60, color: [0.65, 0.68, 0.70] },
    agua:    { sky: [0.30, 0.34, 0.34], tinte: 0.22, far: 55, sigueCielo: false },
    sombra:  1.0   // sin sombra proyectada: todo diluido
  },
  TORMENTA: {   // cielo plomizo: sin luz directa, superficie densa y oscura
    cielo:   [0.18, 0.20, 0.24],
    niebla:  { near: 8, far: 45, tinte: 0.12 },      // cortina de lluvia
    luz:     0.5,
    reflejo: { fuerza: 0.25, curva: 3.0, opacidad: 0.85, color: [0.20, 0.22, 0.26] },
    agua:    { sky: [0.08, 0.10, 0.12], tinte: 0.30, far: 60, sigueCielo: false },
    sombra:  0.95
  },
  // ── Estaciones ─────────────────────────────────────────────────────────────────────────────
  INVIERNO: {   // luz fría de mediodía: cielo pálido/cian, reflejo nítido casi de hielo
    cielo:   [0.70, 0.85, 0.95],
    niebla:  { near: 15, far: 50, tinte: 0.08 },     // neblina nocturna
    //niebla:  { near: 30, far: 110, tinte: 0.05 },    // aire frío, algo de calima
    luz:     0.9,
    reflejo: { fuerza: 0.70, curva: 6.0, opacidad: 0.95, color: 'cielo' },
    agua:    { sky: [0.15, 0.30, 0.40], tinte: 0.12, far: 100, sigueCielo: false },
    sombra:  0.5
  },
  VERANO: {     // sol tropical intenso: azul saturado, sombras duras, agua clara
    cielo:   [0.20, 0.55, 0.95],
    niebla:  false,                                  // aire limpio, mucha visibilidad
    luz:     1.0,
    reflejo: { fuerza: 0.60, curva: 4.5, opacidad: 0.90, color: 'cielo' },
    agua:    { sky: [0.05, 0.45, 0.55], tinte: 0.08, far: 110, sigueCielo: false },
    sombra:  0.4
  }
};

// ── helpers de mezcla ─────────────────────────────────────────────────────────────────────────
const _lerp  = (a, b, t) => a + (b - a) * t;
const _lerpC = (a, b, t) => [_lerp(a[0], b[0], t), _lerp(a[1], b[1], t), _lerp(a[2], b[2], t)];
// El color del reflejo puede ser 'cielo' (sigue al cielo): para poder interpolarlo se resuelve al RGB
// que le tocaría, y al final de la transición se restaura el 'cielo' de verdad aplicando el preset.
const _colorRefl = (refl, cielo) => (refl.color === 'cielo' || refl.color == null) ? cielo.slice() : refl.color.slice();
// La niebla `false` (apagada) se representa como una MUY lejana para poder interpolar sin saltos: así una
// transición a NIEBLA la ve «venir» desde el fondo. Al aterrizar, _aplicaYa pone el valor real (false).
const _niebla = (n) => n ? [n.near, n.far, n.tinte] : [260, 520, 0];

// Aplica un preset de golpe, sin transición.
function _aplicaYa(e) {
  game.cieloColor(e.cielo);
  game.niebla(e.niebla || false);
  game.luz(e.luz != null ? e.luz : 1);
  game.reflejoAgua(e.reflejo);           // incluye color:'cielo' cuando toca
  game.vistaAgua(e.agua);
  game.sunShade = e.sombra;
}

// Lee el estado actual, para poder transicionar DESDE él.
function _estadoActual() {
  const c = game.cieloColor();
  const r = game.reflejoAgua();
  const a = game.vistaAgua();
  const n = game.niebla();
  return {
    cielo:  c.slice(),
    niebla: _niebla(n),
    reflColor: _colorRefl(r, c),
    fuerza: r.fuerza, curva: r.curva, opacidad: r.opacidad,
    aguaSky: (a.sky || [0.1, 0.34, 0.6]).slice(), tinte: a.tinte,
    luz: (typeof game.luz === 'function') ? game.luz() : 1,
    sombra: (typeof game.sunShade === 'number') ? game.sunShade : 0.55
  };
}

game.entorno = function (nombre, opts) {
  if (nombre == null) { console.log('Ambientes: ' + Object.keys(Entornos).join(', ')); return Object.keys(Entornos); }
  const e = Entornos[String(nombre).toUpperCase()];
  if (!e) { console.warn('game.entorno: no existe «' + nombre + '». Hay: ' + Object.keys(Entornos).join(', ')); return; }

  // Cualquier transición en curso se DESMONTA antes de montar otra (misma regla que mc._intro).
  if (mc._entornoRAF) { cancelAnimationFrame(mc._entornoRAF); mc._entornoRAF = 0; }

  const seg = (typeof opts === 'number') ? opts : (opts && +opts.segundos) || 0;
  if (!(seg > 0)) { _aplicaYa(e); mc._entornoActual = String(nombre).toUpperCase(); console.log('[ambiente] ' + mc._entornoActual); return e; }

  const de = _estadoActual();
  const a  = e.agua || {};
  const aB = { sky: (a.sky || de.aguaSky), tinte: (a.tinte != null ? a.tinte : de.tinte) };
  const rB = e.reflejo;
  const colB = _colorRefl(rB, e.cielo);
  const nB = _niebla(e.niebla);
  const t0 = performance.now();
  const paso = () => {
    const t = Math.min(1, (performance.now() - t0) / (seg * 1000));
    const k = t * t * (3 - 2 * t);       // smoothstep: arranca y frena suave
    game.cieloColor(_lerpC(de.cielo, e.cielo, k));
    game.niebla({ near: _lerp(de.niebla[0], nB[0], k), far: _lerp(de.niebla[1], nB[1], k), tinte: _lerp(de.niebla[2], nB[2], k) });
    game.luz(_lerp(de.luz, (e.luz != null ? e.luz : 1), k));
    game.reflejoAgua({ fuerza: _lerp(de.fuerza, rB.fuerza, k), curva: _lerp(de.curva, rB.curva, k), opacidad: _lerp(de.opacidad, rB.opacidad, k) });
    game.reflejoColor(_lerpC(de.reflColor, colB, k));
    game.vistaAgua({ sky: _lerpC(de.aguaSky, aB.sky, k), tinte: _lerp(de.tinte, aB.tinte, k), sigueCielo: false });
    game.sunShade = _lerp(de.sombra, e.sombra, k);
    if (t < 1) { mc._entornoRAF = requestAnimationFrame(paso); }
    else { mc._entornoRAF = 0; _aplicaYa(e); mc._entornoActual = String(nombre).toUpperCase(); console.log('[ambiente] ' + mc._entornoActual); }
  };
  paso();
  return e;
};

// Deja a mano la tabla por si el dueño quiere trastear un preset suelto sin editar el snippet.
game.entornosTabla = Entornos;

toast('Ambientes listos · game.entorno("NIEBLA")  ·  ' + Object.keys(Entornos).length + ' disponibles', 5);
